  `Punto_llegada` varchar(200) NOT NULL,
  `Peso_bruto_total_carga` decimal(12,3) NOT NULL,
  `Unidad_medida_peso_bruto` varchar(3) NOT NULL,
  `Modalidad_traslado` varchar(7) DEFAULT NULL,
  `RUC_Remitente` varchar(11) NOT NULL,
  `RUC_Destinatario` varchar(11) NOT NULL,
  `RUC_Transportista` varchar(11) DEFAULT NULL,
  `RUC_PagadorFlete` varchar(11) DEFAULT NULL,
  `RUC_Proveedor` varchar(11) DEFAULT NULL,
  `Fecha_entrega_bienes_transportista` date DEFAULT NULL,
  PRIMARY KEY (`Serie_numero`),
  KEY `fk_guia_destinatario` (`RUC_Destinatario`),
  KEY `fk_guia_transportista` (`RUC_Transportista`),
  KEY `fk_guia_pagadorflete` (`RUC_PagadorFlete`),
  KEY `fk_guia_proveedor` (`RUC_Proveedor`),
  KEY `idx_guia_fecha` (`Fecha`),
  KEY `idx_guia_ruc_remitente` (`RUC_Remitente`),
  CONSTRAINT `fk_guia_destinatario` FOREIGN KEY (`RUC_Destinatario`) REFERENCES `empresa` (`RUC`),
  CONSTRAINT `fk_guia_pagadorflete` FOREIGN KEY (`RUC_PagadorFlete`) REFERENCES `empresa` (`RUC`),
  CONSTRAINT `fk_guia_proveedor` FOREIGN KEY (`RUC_Proveedor`) REFERENCES `empresa` (`RUC`),
  CONSTRAINT `fk_guia_remitente` FOREIGN KEY (`RUC_Remitente`) REFERENCES `empresa` (`RUC`),
  CONSTRAINT `fk_guia_transportista` FOREIGN KEY (`RUC_Transportista`) REFERENCES `transportista` (`RUC_Transportista`),
  CONSTRAINT `ck_guia_compra` CHECK (((`Motivo_traslado` <> _utf8mb4'Compra') or (`RUC_Proveedor` is not null))),
  CONSTRAINT `ck_guia_modal` CHECK (((`Modalidad_traslado` is null) or (`Modalidad_traslado` in (_utf8mb4'Publico',_utf8mb4'Privado')))),
  CONSTRAINT `ck_guia_modalidad_oblig` CHECK (((`Tipo_guia` <> _utf8mb4'Remitente') or (`Modalidad_traslado` is not null))),
  CONSTRAINT `ck_guia_peso` CHECK ((`Peso_bruto_total_carga` > 0)),
  CONSTRAINT `ck_guia_publico` CHECK (((`Modalidad_traslado` is null) or (`Modalidad_traslado` <> _utf8mb4'Publico') or ((`RUC_Transportista` is not null) and (`Fecha_entrega_bienes_transportista` is not null)))),
  CONSTRAINT `ck_guia_serie` CHECK (regexp_like(`Serie_numero`,_utf8mb4'^[A-Z0-9]{4}-[0-9]{8}$',_utf8mb4'c')),
  CONSTRAINT `ck_guia_tipo` CHECK ((`Tipo_guia` in (_utf8mb4'Remitente',_utf8mb4'Transportista'))),
  CONSTRAINT `ck_guia_unidad` CHECK ((`Unidad_medida_peso_bruto` in (_utf8mb4'TNE',_utf8mb4'KGM')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
