DROP TABLE IF EXISTS `usuario_app`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuario_app` (
  `Id_usuario` int NOT NULL AUTO_INCREMENT,
  `Usuario` varchar(30) NOT NULL,
  `Nombre_completo` varchar(100) NOT NULL,
  `Salt` char(16) NOT NULL,
  `Clave_hash` char(64) NOT NULL,
  `Rol` varchar(15) NOT NULL,
  `Estado` varchar(10) NOT NULL DEFAULT 'ACTIVO',
  `Intentos_fallidos` tinyint NOT NULL DEFAULT '0',
  `Ultimo_acceso` datetime DEFAULT NULL,
  `Fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Fecha_cambio_clave` datetime DEFAULT NULL,
  PRIMARY KEY (`Id_usuario`),
  UNIQUE KEY `uq_usuario_app` (`Usuario`),
  CONSTRAINT `ck_usuario_estado` CHECK ((`Estado` in (_utf8mb4'ACTIVO',_utf8mb4'INACTIVO',_utf8mb4'BLOQUEADO'))),
  CONSTRAINT `ck_usuario_rol` CHECK ((`Rol` in (_utf8mb4'EXTERNO',_utf8mb4'EMPLEADO',_utf8mb4'GESTOR',_utf8mb4'ADMINISTRADOR')))
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
