BEGIN
    DECLARE EXIT HANDLER FOR 1062
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya existe un registro con esa clave o valor unico';
    INSERT INTO EMPRESA (RUC, Razon_Social)
    VALUES (p_ruc, p_razon_social);
